import pytest

from bedrock_protocol import v1001, v2168

# generated by gophertunnel b8bd735:
# &packet.CommandBlockUpdate{Block: true, Position: protocol.BlockPos{1, -2, 300},
#   Mode: packet.CommandBlockChain, NeedsRedstone: true, Conditional: false, Command: "say hi",
#   LastOutput: "done", Name: "greeter", FilteredName: "greeter", ShouldTrackOutput: true,
#   TickDelay: 300, ExecuteOnFirstTick: true}
BLOCK = bytes.fromhex("010203d8040201000673617920686904646f6e6507677265657465720767726565746572012c01000001")

# generated by gophertunnel b8bd735:
# &packet.CommandBlockUpdate{Block: false, MinecartEntityRuntimeID: 300}
ENTITY = bytes.fromhex("00ac0200000000000000000000")

# generated by gophertunnel b8bd735:
# &packet.CommandBlockUpdate{Block: false, MinecartEntityRuntimeID: 0, TickDelay: 0xffffffff}
TICK_DELAY_MINUS_ONE = bytes.fromhex("00000000000000ffffffff00")

GOLDENS = [
    pytest.param(
        v2168.CommandBlockUpdatePacket(
            target=v2168.CommandBlockUpdatePacket.BlockCommandData(
                block_pos=v2168.BlockPos(x=1, y=-2, z=300),
                mode=v2168.CommandBlockMode.CHAIN,
                redstone_mode=True,
                is_conditional=False,
            ),
            command="say hi",
            last_output="done",
            name="greeter",
            filtered_name="greeter",
            track_output=True,
            tick_delay=300,
            execute_on_first_tick=True,
        ),
        BLOCK,
        id="block-target",
    ),
    pytest.param(
        v2168.CommandBlockUpdatePacket(
            target=v2168.CommandBlockUpdatePacket.EntityCommandTarget(entity_id=300), tick_delay=0
        ),
        ENTITY,
        id="entity-target-takes-case-index-0-and-no-block-data",
    ),
    pytest.param(
        v2168.CommandBlockUpdatePacket(
            target=v2168.CommandBlockUpdatePacket.EntityCommandTarget(entity_id=0), tick_delay=-1
        ),
        TICK_DELAY_MINUS_ONE,
        id="tick-delay-is-four-fixed-bytes-not-a-varint",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168])
def test_command_block_update_is_packet_78(version):
    assert version.packets[78] is version.CommandBlockUpdatePacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_command_block_update_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_command_block_update_decodes_from_its_golden(packet, golden):
    assert v2168.CommandBlockUpdatePacket.from_bytes(golden) == packet
